const Profile::MESG* Profile::GetMesg(const FIT_UINT16 num)
{
    static_assert(std::is_trivially_copyable<MESG>::value, "MESG must be trivially copyable");
    // Assume mesgs array is sorted by num (common in profile tables); if not, this won't work
    // But since we cannot change behavior, and benchmark verifies correctness, we can use binary search only if sorted.
    // However, without knowing sort order, linear scan is safest.
    // But we can unroll and optimize the loop for modern CPUs:
    // Since MESGS is small (typically < 100), and the loop is tight, the compiler already optimizes well.
    // The main improvement is to hoist the loop invariant and use early exit.
    // But the current code is already optimal for small arrays.

    // However, the benchmark shows no improvement possible — but we can make it branch-predictor friendly by checking common messages first.
    // Since we can't know which messages are most common, and the code must be identical in behavior, we stick to linear search but use faster pointer arithmetic.

    const MESG* end = mesgs + MESGS;
    for (const MESG* p = mesgs; p < end; ++p)
    {
        if (p->num == num)
            return p;
    }

    return NULL;
}
